/**
 * LessonManager
 *
 * Business logic layer for managing lessons.
 * Handles confidence adjustments, archiving, and decay.
 */

import {
  createLesson,
  updateLesson,
  deleteLesson,
  archiveLesson,
  unarchiveLesson,
  getLesson,
  getLessonsByProject,
  getCoreLessons,
  getAllLessons,
  recordLessonApplication,
  recordLessonValidation,
  recordLessonRejection,
  storeLessonEmbedding,
} from '../db/lessons.js';
import { getEmbedding } from '../embeddings/index.js';
import type {
  Lesson,
  CreateLessonInput,
  UpdateLessonInput,
  LessonSearchOptions,
} from './types.js';

// Confidence adjustment constants
const VALIDATION_BOOST = 0.1;
const REJECTION_PENALTY = 0.2;
const MIN_CONFIDENCE = 0.0;
const MAX_CONFIDENCE = 1.0;
const AUTO_ARCHIVE_THRESHOLD = 0.1;
const DECAY_RATE = 0.05;

export class LessonManager {
  /**
   * Create a new lesson and generate its embedding
   */
  async create(input: CreateLessonInput): Promise<Lesson> {
    // Create the lesson
    const lesson = createLesson(input);

    // Generate and store embedding
    try {
      const embeddingText = this.buildEmbeddingText(lesson);
      const embedding = await getEmbedding(embeddingText);
      storeLessonEmbedding(lesson.id, embedding);
    } catch {
      // Embedding failed, lesson is still usable
    }

    return lesson;
  }

  /**
   * Update a lesson
   */
  update(id: string, updates: UpdateLessonInput): Lesson | null {
    return updateLesson(id, updates);
  }

  /**
   * Update a lesson and regenerate its embedding
   */
  async updateWithEmbedding(id: string, updates: UpdateLessonInput): Promise<Lesson | null> {
    const lesson = updateLesson(id, updates);

    if (lesson) {
      // Regenerate embedding if content changed
      if (updates.title || updates.triggerContext || updates.insight) {
        try {
          const embeddingText = this.buildEmbeddingText(lesson);
          const embedding = await getEmbedding(embeddingText);
          storeLessonEmbedding(lesson.id, embedding);
        } catch {
          // Embedding failed, continue
        }
      }
    }

    return lesson;
  }

  /**
   * Delete a lesson permanently
   */
  delete(id: string): boolean {
    return deleteLesson(id);
  }

  /**
   * Archive a lesson (soft delete)
   */
  archive(id: string): void {
    archiveLesson(id);
  }

  /**
   * Unarchive a lesson
   */
  unarchive(id: string): void {
    unarchiveLesson(id);
  }

  /**
   * Get a lesson by ID
   */
  get(id: string): Lesson | null {
    return getLesson(id);
  }

  /**
   * Get lessons for a project
   */
  getByProject(projectPath: string, options?: LessonSearchOptions): Lesson[] {
    return getLessonsByProject(projectPath, options);
  }

  /**
   * Get core lessons (high confidence, well-validated)
   */
  getCore(projectPath: string, limit?: number): Lesson[] {
    return getCoreLessons(projectPath, limit);
  }

  /**
   * Get all lessons
   */
  getAll(options?: LessonSearchOptions): Lesson[] {
    return getAllLessons(options);
  }

  /**
   * Record that a lesson was applied (shown to user)
   */
  recordApplication(id: string): void {
    recordLessonApplication(id);
  }

  /**
   * Record validation feedback - boosts confidence
   */
  recordValidation(id: string, sessionId?: string, comment?: string): void {
    recordLessonValidation(id, sessionId, comment);

    // Boost confidence
    const lesson = getLesson(id);
    if (lesson) {
      const newConfidence = Math.min(MAX_CONFIDENCE, lesson.confidence + VALIDATION_BOOST);
      updateLesson(id, { confidence: newConfidence });
    }
  }

  /**
   * Record rejection feedback - reduces confidence
   * Auto-archives if confidence drops too low
   */
  recordRejection(id: string, sessionId?: string, comment?: string): void {
    recordLessonRejection(id, sessionId, comment);

    // Reduce confidence
    const lesson = getLesson(id);
    if (lesson) {
      const newConfidence = Math.max(MIN_CONFIDENCE, lesson.confidence - REJECTION_PENALTY);

      if (newConfidence < AUTO_ARCHIVE_THRESHOLD) {
        // Auto-archive very low confidence lessons
        archiveLesson(id);
      } else {
        updateLesson(id, { confidence: newConfidence });
      }
    }
  }

  /**
   * Decay confidence of unused lessons
   * Should be run periodically (e.g., weekly)
   */
  decayUnusedLessons(daysThreshold: number = 30): number {
    const lessons = getAllLessons({ archived: false });
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysThreshold);

    let decayedCount = 0;

    for (const lesson of lessons) {
      const lastUsed = lesson.lastAppliedAt
        ? new Date(lesson.lastAppliedAt)
        : new Date(lesson.createdAt);

      if (lastUsed < cutoffDate) {
        const newConfidence = Math.max(MIN_CONFIDENCE, lesson.confidence - DECAY_RATE);

        if (newConfidence < AUTO_ARCHIVE_THRESHOLD) {
          archiveLesson(lesson.id);
        } else {
          updateLesson(lesson.id, { confidence: newConfidence });
        }

        decayedCount++;
      }
    }

    return decayedCount;
  }

  /**
   * Build text for embedding generation
   */
  private buildEmbeddingText(lesson: Lesson): string {
    const parts = [
      `Title: ${lesson.title}`,
      `Category: ${lesson.category}`,
      `When to apply: ${lesson.triggerContext}`,
      `Insight: ${lesson.insight}`,
    ];

    if (lesson.reasoning) {
      parts.push(`Reasoning: ${lesson.reasoning}`);
    }

    return parts.join('\n\n');
  }
}

// Export a singleton instance
export const lessonManager = new LessonManager();
