/**
 * Synthesis Hook / CLI Command
 *
 * Processes the synthesis queue to extract lessons from sessions.
 * Can be run as a hook or manually via CLI.
 *
 * Usage:
 *   node dist/hooks/synthesize.js        # Process default batch
 *   node dist/hooks/synthesize.js 10     # Process 10 items
 */

import { processSynthesisQueue, getQueueStatus } from '../learning/processQueue.js';

async function main() {
  // Parse limit from args or use default
  const limit = parseInt(process.argv[2], 10) || 5;

  // Get current status
  const status = getQueueStatus();

  if (status.pending === 0) {
    console.log('No sessions pending synthesis.');
    process.exit(0);
  }

  console.log(`Processing up to ${limit} sessions...`);
  console.log(`Queue: ${status.pending} pending, ${status.processing} processing\n`);

  // Process queue
  const result = await processSynthesisQueue(limit);

  // Report results
  console.log('\nSynthesis complete:');
  console.log(`  Processed: ${result.processed}`);
  console.log(`  Lessons created: ${result.lessonsCreated}`);
  console.log(`  Failed: ${result.failed}`);

  if (result.errors.length > 0) {
    console.log('\nErrors:');
    for (const error of result.errors) {
      console.log(`  - ${error}`);
    }
  }

  // Get updated status
  const newStatus = getQueueStatus();
  console.log(`\nQueue now: ${newStatus.pending} pending, ${newStatus.completed} completed`);
  console.log(`Total lessons created: ${newStatus.totalLessonsCreated}`);

  process.exit(result.failed > 0 ? 1 : 0);
}

main().catch((error) => {
  console.error('Synthesis error:', error);
  process.exit(1);
});
