/**
 * Learning Module Types
 *
 * Type definitions for the lesson learning system.
 */

export type LessonCategory =
  | 'architecture_decision'
  | 'anti_pattern'
  | 'bug_pattern'
  | 'project_convention'
  | 'dependency_knowledge'
  | 'domain_knowledge'
  | 'workflow'
  | 'other';

export type LessonSourceType = 'synthesized' | 'manual' | 'imported';

export type FeedbackType = 'validated' | 'rejected' | 'modified';

export interface Lesson {
  id: string;
  projectPath: string;
  category: LessonCategory;
  title: string;
  triggerContext: string;
  insight: string;
  reasoning?: string;
  confidence: number;
  timesApplied: number;
  timesValidated: number;
  timesRejected: number;
  sourceSessionId?: string;
  sourceType: LessonSourceType;
  archived: boolean;
  createdAt: string;
  updatedAt: string;
  lastAppliedAt?: string;
}

export interface CreateLessonInput {
  projectPath: string;
  category: LessonCategory;
  title: string;
  triggerContext: string;
  insight: string;
  reasoning?: string;
  confidence?: number;
  sourceSessionId?: string;
  sourceType?: LessonSourceType;
}

export interface UpdateLessonInput {
  category?: LessonCategory;
  title?: string;
  triggerContext?: string;
  insight?: string;
  reasoning?: string;
  confidence?: number;
  archived?: boolean;
}

export interface LessonFeedback {
  id: number;
  lessonId: string;
  sessionId?: string;
  feedbackType: FeedbackType;
  comment?: string;
  createdAt: string;
}

export interface SynthesisQueueItem {
  id: number;
  sessionId: string;
  projectPath: string;
  queuedAt: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  processedAt?: string;
  lessonsCreated: number;
  error?: string;
}

export interface LessonSearchOptions {
  category?: LessonCategory;
  archived?: boolean;
  minConfidence?: number;
  limit?: number;
}

export interface ConsultOptions {
  maxSemantic?: number;
  maxCore?: number;
}

export interface ConsultResult {
  lessons: Lesson[];
  formattedContext: string;
}

/**
 * Raw lesson extracted from synthesis (before deduplication)
 */
export interface RawLesson {
  category: LessonCategory;
  title: string;
  triggerContext: string;
  insight: string;
  reasoning?: string;
  confidence: number;
}

/**
 * Category display names for UI
 */
export const LESSON_CATEGORY_NAMES: Record<LessonCategory, string> = {
  architecture_decision: 'Architecture Decision',
  anti_pattern: 'Anti-Pattern',
  bug_pattern: 'Bug Pattern',
  project_convention: 'Project Convention',
  dependency_knowledge: 'Dependency Knowledge',
  domain_knowledge: 'Domain Knowledge',
  workflow: 'Workflow',
  other: 'Other',
};

